@dataclass(repr=False, eq=False)
class AssessedElementRegularTimePoint(Identity):
    '''
    Assessed element instruction value at a given point in time.
    '''

    enabled: Optional[bool] = field(
        default=None,
        metadata={
        'type': 'Attribute',
        'stereotypes': ['NC', 'Attribute'],
        'minOccurs': '0',
        'maxOccurs': '1',
        'namespace': 'http://entsoe.eu/ns/nc#',
        'serialize': True,
        })
    '''
    It identifies if the assessed element is enabled. True means enabled,
    False means disabled.
    '''
    
    appointedMargin: Optional[ PerCent ] = field(
        default=None,
        metadata={
        'type': 'Attribute',
        'stereotypes': ['NC', 'Attribute'],
        'minOccurs': '0',
        'maxOccurs': '1',
        'namespace': 'http://entsoe.eu/ns/nc#',
        'serialize': True,
        })
    '''
    The percentage (appointed to a region) of the remaining margin obtained
    in the grid model to reach its current limit. The maximum percentage
    shall by default be 10% of the remaining margin.
    It is only used when an assessed element is considered conservative
    for a region.
    The allowed value range is [0,100].
    '''
    
    maxFlow: Optional[ ActivePower ] = field(
        default=None,
        metadata={
        'type': 'Attribute',
        'stereotypes': ['NC', 'Attribute'],
        'minOccurs': '0',
        'maxOccurs': '1',
        'namespace': 'http://entsoe.eu/ns/nc#',
        'serialize': True,
        })
    '''
    Maximum flow on an a conducting equipment or a collection of conducting
    equipment forming a power transfer corridor. For assessed elements
    that is becomes critical due to contingency, this value represents
    the maximum flow with remedial action taken into consideration.
    '''
    
    scannedThresholdMargin: Optional[ PerCent ] = field(
        default=None,
        metadata={
        'type': 'Attribute',
        'stereotypes': ['NC', 'Attribute'],
        'minOccurs': '0',
        'maxOccurs': '1',
        'namespace': 'http://entsoe.eu/ns/nc#',
        'serialize': True,
        })
    '''
    Threshold percentage that a scanned element can be overloaded, on a
    given element, on top of any overload prior to optimisation (default=
    5%). e.g. Initial loading of the element is 110%, with a 5% scanned
    threshold margin, the new maximum is 115% of the limit (e.g. PATL,
    TATL, etc).
    The allowed value range is [0,100].
    '''
    
    virtualPositiveMargin: Optional[ PerCent ] = field(
        default=None,
        metadata={
        'type': 'Attribute',
        'stereotypes': ['NC', 'Attribute'],
        'minOccurs': '0',
        'maxOccurs': '1',
        'namespace': 'http://entsoe.eu/ns/nc#',
        'serialize': True,
        })
    '''
    A margin defined only for scanned AssessedElement (If AssessedElement.ScannedForRegion
    is present) in order to represent the influence of available remedial
    action which is not cross-border relevant remedial action.
    The margin is modifying the limits used for the assessment whatever
    the limit it is (e.g. PATL, TATL).This symbolizes a remedial action
    that can be applied internally by the System Operator. It will be resolved
    by the System Operator and not by the optimization of remedial actions.
    The attribute shall be a positive value.
    The allowed value range is [0,100].
    '''
    
    AssessedElementRegularSchedule: Optional[AssessedElementRegularSchedule] = field(
        default=None,
        metadata={
        'type': 'Association',
        'stereotypes': ['OfAggregate', 'NC'],
        'minOccurs': '0',
        'maxOccurs': '1',
        'inverse': 'AssessedElementRegularSchedule.AssessedElementRegularTimePoint',
        'namespace': 'http://entsoe.eu/ns/nc#',
        'serialize': True,
        })
    '''
    Assessed element regular schedule which has assessed element regular
    time points.
    '''
    
    @property
    def __namespace__(self):
        return 'http://entsoe.eu/ns/nc#'
    @property
    def __package__(self):
        return 'ExtSchedule'
    @property
    def __minOccurs__(self):
        return '0'
    @property
    def __maxOccurs__(self):
        return 'unbounded'
    
