@dataclass(repr=False, eq=False)
class GridStateAlteration(IdentifiedObject):
    '''
    Grid state alteration is a change of values describing state (operating
    point) of one element in the grid model compared to the base case.
    '''

    enabled: Optional[bool] = field(
        default=None,
        metadata={
        'type': 'Attribute',
        'stereotypes': ['NC', 'Attribute'],
        'minOccurs': '0',
        'maxOccurs': '1',
        'namespace': 'http://entsoe.eu/ns/nc#',
        'serialize': True,
        })
    '''
    The status of the GridStateAlteration set by an operation or by a signal
    resulting from a control action.
    '''
    
    maximumPerDay: Optional[int] = field(
        default=None,
        metadata={
        'type': 'Attribute',
        'stereotypes': ['NC', 'Attribute'],
        'minOccurs': '0',
        'maxOccurs': '1',
        'namespace': 'http://entsoe.eu/ns/nc#',
        'serialize': True,
        })
    '''
    Maximum number of alterations per day.
    '''
    
    minimumActivation: Optional[str] = field(
        default=None,
        metadata={
        'type': 'Attribute',
        'stereotypes': ['NC', 'Attribute'],
        'minOccurs': '0',
        'maxOccurs': '1',
        'namespace': 'http://entsoe.eu/ns/nc#',
        'serialize': True,
        })
    '''
    Minimum time duration between activating the same grid state alteration.
    '''
    
    normalEnabled: Optional[bool] = field(
        default=None,
        metadata={
        'type': 'Attribute',
        'stereotypes': ['NC', 'Attribute'],
        'minOccurs': '0',
        'maxOccurs': '1',
        'namespace': 'http://entsoe.eu/ns/nc#',
        'serialize': True,
        })
    '''
    The default/normal value used when other active signal/values are missing.
    '''
    
    timePerStage: Optional[str] = field(
        default=None,
        metadata={
        'type': 'Attribute',
        'stereotypes': ['NC', 'Attribute'],
        'minOccurs': '0',
        'maxOccurs': '1',
        'namespace': 'http://entsoe.eu/ns/nc#',
        'serialize': True,
        })
    '''
    Time to implement a stage of a grid state alteration. If a grid state
    alteration consists of multiple stages (e.g. A step on a power transformer),
    this duration comes in addition to the timeToImplement and need to
    be multiplied by the number of stages. A stage can also be defined
    as MW in the case of regulating production.
    '''
    
    participationFactor: Optional[ PerCent ] = field(
        default=None,
        metadata={
        'type': 'Attribute',
        'stereotypes': ['NC', 'Attribute'],
        'minOccurs': '0',
        'maxOccurs': '1',
        'namespace': 'http://entsoe.eu/ns/nc#',
        'serialize': True,
        })
    '''
    Participation factor describing the entity part of the active power
    provided by a collection of entities (e.g. an active power forecast
    to a collection of entities is divided to each of the member entity
    according to the participation factor). Must be a positive value.
    In the case of a sharing strategy, the distribution is following entities
    value (V) equals aggregated value (T) divided by sum of participation
    factors (PF), i.e. V=T/sum(PF).
    In the case of priority strategy, the item with the lowest number gets
    allocated energy first.
    e.g. If 0 this grid alteration does not participate. The sum of all
    participation factors for all grid state alterations associated with
    same remedial action shall be equal to 100%.
    '''
    
    GridStateAlterationSchedule: list[GridStateAlterationSchedule] = field(
        default_factory=list,
        metadata={
        'type': 'Association',
        'stereotypes': ['NC'],
        'minOccurs': '0',
        'maxOccurs': 'unbounded',
        'inverse': 'GridStateAlterationSchedule.GridStateAlteration',
        'namespace': 'http://entsoe.eu/ns/nc#',
        'serialize': False,
        })
    '''
    Grid state alteration schedule associated with a grid state alteration.
    '''
    
    GridStateAlterationCollection: Optional[GridStateAlterationCollection] = field(
        default=None,
        metadata={
        'type': 'Association',
        'stereotypes': [],
        'minOccurs': '0',
        'maxOccurs': '1',
        'inverse': 'GridStateAlterationCollection.GridStateAlteration',
        'namespace': 'http://entsoe.eu/ns/nc#',
        'serialize': True,
        })
    '''
    The collection that has a GridStateAlteration.
    '''
    
    GridStateAlterationRemedialAction: Optional[GridStateAlterationRemedialAction] = field(
        default=None,
        metadata={
        'type': 'Association',
        'stereotypes': ['NC'],
        'minOccurs': '0',
        'maxOccurs': '1',
        'inverse': 'GridStateAlterationRemedialAction.GridStateAlteration',
        'namespace': 'http://entsoe.eu/ns/nc#',
        'serialize': True,
        })
    '''
    The grid state alteration remedial action associated with a given grid
    state alteration.
    '''
    
    @property
    def __namespace__(self):
        return 'http://entsoe.eu/ns/nc#'
    @property
    def __package__(self):
        return 'ExtRemedialAction'
    @property
    def __minOccurs__(self):
        return '0'
    @property
    def __maxOccurs__(self):
        return 'unbounded'
    
