@stereotype(CIMStereotype.NC)
@stereotype(CIMStereotype.enumeration)
@stereotype(CIMStereotype.Attribute)
class BaseTimeSeriesKind(Enum):
    '''
    Kind of time series.
    '''

    actual = 'actual'
    '''
    Time series is actual data. The values represent measured or calculated
    values that represent the actual behaviour.
    '''
    
    forecast = 'forecast'
    '''
    Time series is forecast data. The values represent the result of scientific
    predictions based on historical time stamped data.
    '''
    
    hindcast = 'hindcast'
    '''
    Time series is hindcast data. The value represent probable past (historic)
    condition given by calculation done using actual values. For instance,
    determine the among of wind based on the energy produced by wind. However,
    hindcast is typical the result of a simulated forecasts for historical
    periods.
    '''
    
    schedule = 'schedule'
    '''
    Time series is schedule data. The values represent the result of a
    committed and plan forecast data that has been through a quality control
    and could incur penalty when not followed.
    '''
    
    @property
    def __namespace__(self):
        return 'http://entsoe.eu/ns/nc#'
    @property
    def __package__(self):
        return 'ExtSchedule'
    @property
    def __minOccurs__(self):
        return '0'
    @property
    def __maxOccurs__(self):
        return 'unbounded'
    
